                      ]
                    },
                    "then": {
                      "$ref": "request.duration"
                    }
                  }
                },
                "resolution": {
                  "$omitEmpty": {
                    "$lower": {
                      "$ref": "request.resolution"
                    }
                  }
                }
              },
              {
                "$if": {
                  "condition": {
                    "$in": [
                      {
                        "$ref": "request.model"
