          },
          {
            "name": "duration",
            "type": "integer",
            "mapping": "seconds",
            "description": "整数秒数。"
          },
          {
            "name": "resolution",
            "type": "string",
            "mapping": "resolution",
            "description": "画质。"
          },
          {
            "name": "aspectRatio",
            "type": "string",
            "mapping": "aspect_ratio",
            "description": "画幅。"
          },
          {
            "name": "images",
            "type": "media[]",
            "mapping": "references",
            "description": "参考图片。"
          },
