            "name": "videos",
            "type": "media[]",
            "mapping": "references",
            "description": "参考视频。"
          },
          {
            "name": "audios",
            "type": "media[]",
            "mapping": "references",
            "description": "参考音频。"
          }
        ],
        "validations": [
          {
            "assert": {
              "$in": [
                {
                  "$ref": "request.model"
                },
                [
                  "sd-native-full-2.0",
                  "sd-native-full-2.5",
                  "原生不卡人脸-全参2.0",
                  "原生不卡人脸-全参2.5"
                ]
              ]
            },
            "message": "此协议支持全参 2.0 / 2.5，请选择对应模型。"
          }
        ],
        "create": {
          "method": "POST",
          "path": "/v1/videos",
          "contentType": "application/json",
          "headers": {
            "Idempotency-Key": {
              "$ref": "request.extra.idempotencyKey"
            }
          },
          "body": {
            "model": {
              "$ref": "request.model"
            },
            "prompt": {
              "$ref": "request.prompt"
            },
            "seconds": {
              "$ref": "request.duration"
            },
            "resolution": {
              "$ref": "request.resolution"
            },
            "aspect_ratio": {
              "$ref": "request.aspectRatio"
            },
            "references": {
              "$omitEmpty": {
                "$concatArrays": [
                  {
                    "$map": {
                      "from": {
                        "$ref": "request.images"
                      },
                      "as": "media",
                      "in": {
                        "type": "image",
                        "source": {
                          "$ref": "media.value"
                        },
                        "role": "reference"
                      }
                    }
                  },
                  {
                    "$map": {
                      "from": {
                        "$ref": "request.videos"
                      },
                      "as": "media",
                      "in": {
                        "type": "video",
                        "source": {
                          "$ref": "media.value"
                        },
                        "role": "reference",
                        "duration_seconds": {
                          "$divide": [
                            {
                              "$ref": "media.metadata.durationMs"
                            },
                            1000
                          ]
                        }
                      }
                    }
                  },
                  {
                    "$map": {
                      "from": {
                        "$ref": "request.audios"
                      },
                      "as": "media",
