| `create.path` | `"/v1/projects/{{request.providerOptions.vertex-veo.project}}/locations/{{request.providerOptions.vertex-veo.location}}/publishers/google/models/{{model}}:predictLongRunning"` |
| `create.contentType` | `"application/json"` |
| `create.body` | `{"$merge":[{"model":{"$ref":"request.model"},"prompt":{"$ref":"request.prompt"},"images":{"$omitEmpty":{"$map":{"from":{"$ref":"request.images"},"as":"media","in":{"$ref":"media.value"}}}},"videos":{"$omitEmpty":{"$map":{"from":{"$ref":"request.videos"},"as":"media","in":{"$ref":"media.value"}}}},"audios":{"$omitEmpty":{"$map":{"from":{"$ref":"request.audios"},"as":"media","in":{"$ref":"media.value"}}}},"duration":{"$omitEmpty":{"$ref":"request.duration"}},"aspect_ratio":{"$omitEmpty":{"$ref":"request.aspectRatio"}},"resolution":{"$omitEmpty":{"$ref":"request.resolution"}},"parameters":{"$omitEmpty":{"$ref":"request.providerOptions.vertex-veo.parameters"}}},{"$coalesce":[{"$ref":"request.providerOptions.vertex-veo.body"},{"$ref":"request.providerOptions.vertex-veo.extra_body"},{}]}]}` |
| `poll.method` | `"GET"` |
| `poll.path` | `"/v1/{{taskId}}"` |
| `poll.contentType` | `"application/json"` |

## Provider 扩展键

- `providerOptions.vertex-veo.body`
- `providerOptions.vertex-veo.extra_body`
- `providerOptions.vertex-veo.location`
- `providerOptions.vertex-veo.parameters`
